package os.aios.core.workspace;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.text.Normalizer;import java.util.*;

/** Unified packaged/manual/learned skill asset facade. Bodies live only in versioned files. */
final class WorkspaceSkills{
 private final WorkspaceStore store;private final SQLiteDatabase db;private final SkillFileStore files;private boolean dreamEvidence;
 WorkspaceSkills(WorkspaceStore s,SQLiteDatabase d){store=s;db=d;files=new SkillFileStore(s);reconcilePublications();}
 static void migrate(SQLiteDatabase db){
  db.execSQL("CREATE TABLE IF NOT EXISTS skill_evidence(id TEXT PRIMARY KEY,tool TEXT NOT NULL,package TEXT NOT NULL,app_version TEXT NOT NULL,created_at INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS skill_publications(id TEXT PRIMARY KEY,skill_id TEXT NOT NULL,expected_revision INTEGER NOT NULL,target_revision INTEGER NOT NULL,state TEXT NOT NULL,asset_hash TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS skill_evidence_context(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,request_id TEXT NOT NULL,session_id TEXT NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS skill_uses(id TEXT PRIMARY KEY,skill_id TEXT NOT NULL,revision INTEGER NOT NULL,evidence_id TEXT NOT NULL,kind TEXT NOT NULL,result TEXT NOT NULL,created_at INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS skill_health(skill_id TEXT NOT NULL,revision INTEGER NOT NULL,capability_id TEXT NOT NULL,state TEXT NOT NULL,app_version TEXT NOT NULL,evidence_id TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(skill_id,revision,capability_id))");
  db.execSQL("CREATE TABLE IF NOT EXISTS skill_migrations(skill_id TEXT PRIMARY KEY,state TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',migrated_at INTEGER NOT NULL DEFAULT 0)");
 }
 static String normalize(String s){return Normalizer.normalize(s,Normalizer.Form.NFKC).toLowerCase(Locale.ROOT).replaceAll("\\s+","").trim();}
 private void reconcilePublications(){try{for(JSONObject m:files.list()){String skill=m.getString("id");long revision=m.getLong("revision");if(store.rows(db,"SELECT id FROM skill_publications WHERE skill_id=? AND target_revision=? AND state IN ('published','recovered')",skill,Long.toString(revision)).length()==0)ledger("recovered:"+skill+":"+revision,skill,Math.max(0,revision-1),revision,"recovered","","");}db.execSQL("UPDATE skill_publications SET state='failed',error='Prepared asset absent after restart',updated_at=? WHERE state='prepared'",new Object[]{WorkspaceStore.now()});}catch(Exception e){throw new IllegalStateException("Skill publication recovery failed",e);}}
 /** Explicit source deletion removes learned assets; ordinary deletion only invalidates evidence. */
 void deleteLearnedFromThread(String thread)throws Exception{
  JSONArray linked=store.rows(db,"SELECT DISTINCT u.skill_id FROM skill_uses u JOIN skill_evidence_context c ON c.id=u.evidence_id WHERE c.thread_id=?",thread);
  for(int i=0;i<linked.length();i++){String id=linked.getJSONObject(i).getString("skill_id");JSONObject m=files.metadata(id,true);if(m!=null&&!m.optBoolean("deleted")&&"learned".equals(m.optString("source")))call("skill.delete",new JSONObject().put("id",id).put("expected_revision",m.getLong("revision")));}
 }
 JSONObject learnDream(JSONObject p)throws Exception{dreamEvidence=true;try{return call("skill.learn",p);}finally{dreamEvidence=false;}}
 JSONObject call(String op,JSONObject p)throws Exception{
  String id=p.optString("id","");
  if(op.equals("skill.list")||op.equals("skill.search"))return search(p);
  if(op.equals("skill.versions"))return files.versions(id);
  if(op.equals("skill.resource.get"))return files.resource(p);
  if(op.equals("skill.get")){JSONObject item="body".equals(p.optString("view"))?files.bodyView(id):files.get(id),proof=item.optJSONObject("evidence");String pkg=item.optString("package"),current=pkg.isEmpty()?"":store.skillAppVersion(pkg);return item.put("health",health(item)).put("resolved_dependencies",dependencies(item,new HashSet<>(),0)).put("effective_state",summary(item).optString("effective_state")).put("evidence_traceable",summary(item).optBoolean("evidence_traceable")).put("samples",summary(item).getJSONArray("samples")).put("current_app_version",current).put("requires_revalidation",summary(item).optBoolean("requires_revalidation"));}
  if(op.equals("skill.create")||op.equals("skill.learn"))return create(op,p);
  JSONObject old=files.get(id);store.revision(old,p);
  if(op.equals("skill.report"))return report(old,p);
  if(op.equals("skill.merge")){
   JSONObject target=files.get(p.getString("target_id"));if(target.getLong("revision")!=p.getLong("target_revision"))throw new IllegalStateException("Merge target changed");
   if(old.getString("id").equals(target.getString("id"))||old.optBoolean("user_edited")||!old.optBoolean("enabled",true)||!target.optBoolean("enabled",true)||!target.optString("lifecycle").equals("available")||old.optString("capability_id").isEmpty()||!old.optString("capability_id").equals(target.optString("capability_id")))return new JSONObject().put("ignored","merge_not_verified");
   JSONObject metadata=new JSONObject(old.toString());String body=metadata.getString("content_md");JSONObject assets=metadata.getJSONObject("assets");metadata.remove("content_md");metadata.remove("assets");metadata.put("lifecycle","archived").put("replaced_by",target.getString("id"));return publish(metadata,body,assets,old.getLong("revision"));
  }
  if(op.equals("skill.rollback")){JSONObject result=files.rollback(id,p.getLong("target_revision"),old.getLong("revision"));ledger(WorkspaceStore.id(),id,old.getLong("revision"),result.getLong("revision"),"published",SkillFileStore.hash(result.getString("content_md")),"");result.remove("assets");return result;}
  if(op.equals("skill.delete")){files.delete(id,old.getLong("revision"));ledger(WorkspaceStore.id(),id,old.getLong("revision"),old.getLong("revision")+1,"deleted","","");return new JSONObject().put("id",id).put("deleted",true);}
  if(!op.equals("skill.update"))throw new IllegalArgumentException("Unknown skill action");
  JSONObject next=new JSONObject(old.toString());for(String key:new String[]{"title","description","content_md"})if(p.has(key))next.put(key,WorkspaceStore.text(p,key,key.equals("content_md")?24000:key.equals("description")?500:160,false));if(p.has("enabled"))next.put("enabled",p.getBoolean("enabled"));if(p.has("assets")&&p.has("assets_patch"))throw new IllegalArgumentException("Choose assets or assets_patch");if(p.has("assets"))next.put("assets",p.getJSONObject("assets"));if(p.has("assets_patch")){JSONObject assets=next.getJSONObject("assets"),patch=p.getJSONObject("assets_patch");Iterator<String> keys=patch.keys();while(keys.hasNext()){String key=keys.next();if(patch.isNull(key))assets.remove(key);else assets.put(key,patch.getString(key));}}next.put("user_edited",true);if(p.has("title"))next.put("dedupe",normalize(old.optString("package"))+":"+normalize(p.getString("title")));String body=next.getString("content_md");JSONObject assets=next.optJSONObject("assets");if(assets==null)assets=new JSONObject();next.remove("content_md");next.remove("assets");return publish(next,body,assets,old.getLong("revision"));
 }
 private JSONObject search(JSONObject p)throws Exception{
  int limit=Math.max(1,Math.min(100,p.optInt("limit",20))),offset=Math.max(0,p.optInt("offset",0));String q=p.optString("query","").toLowerCase(Locale.ROOT),domain=p.optString("domain",""),kind=p.optString("knowledge_kind","");
  if(q.length()>200||domain.length()>80)throw new IllegalArgumentException("Search too long");List<JSONObject> matches=new ArrayList<>();
  for(JSONObject m:files.list()){
   if(m.optBoolean("deleted")||m.optString("lifecycle").equals("archived")||p.optBoolean("enabled_only")&&!m.optBoolean("enabled",true)||!domain.isEmpty()&&!domain.equals(m.optString("domain"))||!kind.isEmpty()&&!kind.equals(m.optString("knowledge_kind")))continue;
   JSONObject item=summary(m);String hay=(m.optString("title")+" "+m.optString("description")+" "+m.optString("package")+" "+store.skillAppLabel(m.optString("package"))+" "+m.optString("domain")+" "+m.optString("tags")+" "+m.optString("capability_id")).toLowerCase(Locale.ROOT);
   if(q.isEmpty()||hay.contains(q))matches.add(item);
   JSONArray capabilities=m.optJSONArray("capabilities");if(capabilities!=null)for(int i=0;i<capabilities.length();i++){
    JSONObject capability=capabilities.getJSONObject(i);String words=(capability.optString("name")+" "+capability.optString("summary")+" "+capability.optString("capability_id")+" "+m.optString("package")).toLowerCase(Locale.ROOT);
    if(!q.isEmpty()&&!words.contains(q))continue;JSONObject fragment=summary(m);fragment.put("effective_state",m.optBoolean("enabled",true)?health(m,capability.getString("capability_id")).optString("state",fragment.optString("effective_state")):"user_disabled").put("health",health(m,capability.getString("capability_id"))).put("capability_id",capability.getString("capability_id")).put("title",capability.getString("name")).put("description",capability.getString("summary")).put("resource_path",capability.getString("path")).put("conditions",capability.optString("conditions"));JSONObject branchHealth=health(m,capability.getString("capability_id"));if(branchHealth.has("app_version")&&fragment.optString("current_app_version").equals(branchHealth.optString("app_version")))fragment.put("requires_revalidation",false);if(fragment.optBoolean("requires_revalidation")&&!Set.of("auto_paused","user_disabled").contains(fragment.optString("effective_state")))fragment.put("effective_state","needs_revalidation");matches.add(fragment);
   }
  }
  String application=p.optString("application").toLowerCase(Locale.ROOT),stateFilter=p.optString("state");matches.removeIf(m->!application.isEmpty()&&!(m.optString("package")+" "+m.optString("app_label")).toLowerCase(Locale.ROOT).contains(application)||!stateFilter.isEmpty()&&!stateFilter.equals(m.optString("effective_state")));
  matches.sort((a,b)->Long.compare(b.optLong("updated_at"),a.optLong("updated_at")));JSONArray out=new JSONArray();int bytes=0;
  for(int i=offset;i<matches.size()&&out.length()<limit;i++){JSONObject m=matches.get(i);int n=m.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(bytes+n>24000)break;out.put(m);bytes+=n;}
  return new JSONObject().put("items",out).put("total",matches.size()).put("next_offset",offset+out.length()<matches.size()?offset+out.length():JSONObject.NULL).put("search_mode","literal_summary").put("fallback","Use another query, omit category filters, or browse all pages; zero matches is not proof of absence.");
 }
 private JSONObject summary(JSONObject m)throws Exception{
  JSONObject out=new JSONObject();for(String key:new String[]{"id","title","description","package","domain","knowledge_kind","capability_id","source","enabled","user_edited","revision","updated_at","lifecycle","verification_kind"})if(m.has(key))out.put(key,m.get(key));out.put("resource_path","SKILL.md");String pkg=m.optString("package"),version=pkg.isEmpty()?"":store.skillAppVersion(pkg);JSONObject proof=m.optJSONObject("evidence");out.put("current_app_version",version).put("requires_revalidation",!pkg.isEmpty()&&(proof==null||!version.equals(proof.optString("app_version"))));
  out.put("app_label",store.skillAppLabel(pkg)).put("evidence_traceable",proof!=null&&!proof.optString("id").isEmpty()&&store.rows(db,"SELECT id FROM skill_evidence WHERE id=?",proof.optString("id")).length()>0);JSONObject whole=health(m,"");if(whole.has("app_version")&&version.equals(whole.optString("app_version")))out.put("requires_revalidation",false);String effective=whole.optString("state",m.optString("lifecycle","unverified"));if(out.optBoolean("requires_revalidation")&&!effective.equals("auto_paused"))effective="needs_revalidation";out.put("effective_state",m.optBoolean("enabled",true)?effective:"user_disabled");
  out.put("health",health(m));out.put("samples",store.rows(db,"SELECT kind,result,count(*) AS count FROM skill_uses WHERE skill_id=? GROUP BY kind,result",m.getString("id")));return out;
 }
 private JSONObject create(String op,JSONObject p)throws Exception{boolean learned=op.equals("skill.learn");String title=WorkspaceStore.text(p,"title",160,false),description=WorkspaceStore.text(p,"description",500,false),body=WorkspaceStore.text(p,"content_md",24000,false),pkg=p.optString("package",""),domain=p.optString("domain","");if(!pkg.isEmpty()&&!pkg.matches("[A-Za-z0-9_]+(\\.[A-Za-z0-9_]+)+"))throw new IllegalArgumentException("Invalid package");if(domain.length()>80)throw new IllegalArgumentException("Invalid domain");JSONObject evidence=new JSONObject();if(learned){JSONObject proof=store.require(db,"skill_evidence",p.getString("evidence_id"));
   if(!dreamEvidence&&!p.optString("_caller_thread").isEmpty()){JSONObject owner=store.require(db,"skill_evidence_context",p.getString("evidence_id"));if(!p.getString("_caller_thread").equals(owner.getString("thread_id")))throw new SecurityException("Learning evidence belongs to another thread");}
   if(!Set.of("independent","demonstration","corrected").contains(p.optString("verification_kind","independent")))throw new IllegalArgumentException("Incomplete or unknown results cannot publish successful skills");
   if(!pkg.isEmpty()&&!store.skillAppVersion(pkg).equals(proof.optString("app_version")))throw new IllegalArgumentException("App version changed; verify again");if(WorkspaceStore.now()-proof.getLong("created_at")>(dreamEvidence?14:1)*86400000L)throw new IllegalArgumentException("Evidence expired; observe again");if(!proof.getString("package").isEmpty()&&!pkg.equals(proof.getString("package")))throw new IllegalArgumentException("Evidence app differs");WorkspaceStore.text(p,"verification",1200,false);evidence=new JSONObject(proof.toString()).put("verification",p.getString("verification"));}
  String dedupe=normalize(pkg)+":"+normalize(title);JSONObject old=p.optString("id").isEmpty()?files.findDedupe(dedupe):files.metadata(p.getString("id"),true);if(old==null&&learned)old=files.findCapability(p.optString("capability_id"),pkg);if(!p.optString("id").isEmpty()&&old==null)throw new IllegalArgumentException("Merge target missing");if(old!=null){if(!learned)throw new IllegalArgumentException("已有同名技能，请编辑现有技能");if(old.optBoolean("deleted"))return new JSONObject().put("ignored","user_deleted");if(!old.optBoolean("enabled",true))return new JSONObject().put("ignored","user_override").put("id",old.getString("id"));if(!pkg.equals(old.optString("package")))throw new IllegalArgumentException("Merge app differs");JSONObject previous=files.get(old.getString("id"));String use=SkillFileStore.hash(p.getString("evidence_id")+":"+old.getString("id"));
   if(store.rows(db,"SELECT id FROM skill_uses WHERE id=?",use).length()>0){previous.remove("assets");return previous.put("merge_status","unchanged");}
   boolean protectedVersion=old.optBoolean("user_edited"),changed=!protectedVersion&&(!previous.getString("content_md").trim().equals(body.trim())||p.has("assets_patch"));
   if(changed){store.revision(previous,p);JSONObject assets=previous.getJSONObject("assets");if(p.has("assets_patch")){JSONObject patch=p.getJSONObject("assets_patch");Iterator<String> keys=patch.keys();while(keys.hasNext()){String k=keys.next();if(patch.isNull(k))assets.remove(k);else assets.put(k,patch.getString(k));}}JSONObject next=new JSONObject(previous.toString());next.remove("content_md");next.remove("assets");next.put("description",description).put("evidence",evidence).put("lifecycle","available");for(String key:new String[]{"capability_id","knowledge_kind","capabilities","tags","parameters","success_conditions","dependencies"})if(p.has(key))next.put(key,p.get(key));previous=publish(next,body,assets,old.getLong("revision"));}
   db.execSQL("INSERT OR IGNORE INTO skill_uses VALUES(?,?,?,?,?,'verified',?)",new Object[]{use,old.getString("id"),previous.getLong("revision"),p.getString("evidence_id"),p.optString("verification_kind","independent"),WorkspaceStore.now()});
   verified(previous,p,evidence);previous.remove("assets");return previous.put("merge_status",protectedVersion?"protected_evidence_added":changed?"updated":"evidence_added");}
  JSONObject m=new JSONObject().put("id",WorkspaceStore.id()).put("title",title).put("description",description).put("domain",domain).put("package",pkg).put("source",learned?"learned":"manual").put("enabled",true).put("user_edited",!learned).put("dedupe",dedupe).put("evidence",evidence);m.put("lifecycle",learned?"available":"unverified").put("verification_kind",learned?p.optString("verification_kind","independent"):"manual_unverified");for(String key:new String[]{"capability_id","knowledge_kind","capabilities","tags","parameters","success_conditions","dependencies"})if(p.has(key))m.put(key,p.get(key));
  JSONObject result=publish(m,body,p.optJSONObject("assets")!=null?p.getJSONObject("assets"):new JSONObject(),0);
  if(learned){String use=SkillFileStore.hash(p.getString("evidence_id")+":"+m.getString("id"));db.execSQL("INSERT OR IGNORE INTO skill_uses VALUES(?,?,?,?,?,'verified',?)",new Object[]{use,m.getString("id"),result.getLong("revision"),p.getString("evidence_id"),p.optString("verification_kind","independent"),WorkspaceStore.now()});verified(result,p,evidence);}return result.put("merge_status","created");
 }
 private JSONArray dependencies(JSONObject item,Set<String> seen,int depth)throws Exception{
  JSONArray result=new JSONArray(),deps=item.optJSONArray("dependencies");if(deps==null)return result;
  if(depth>8||!seen.add(item.getString("id")))throw new IllegalStateException("Skill dependency cycle or excessive depth");
  for(int i=0;i<deps.length();i++){String id=deps.getString(i);JSONObject m=files.metadata(id,false),value=new JSONObject().put("id",id);
   if(m!=null&&m.optString("lifecycle").equals("archived")){JSONObject replacement=files.metadata(m.getString("replaced_by"),false);if(replacement!=null&&replacement.optString("capability_id").equals(m.optString("capability_id")))m=replacement;else m=null;}
   boolean available=m!=null&&m.optBoolean("enabled",true)&&!Set.of("auto_paused","archived").contains(m.optString("lifecycle"))&&!health(m,"").optString("state").equals("auto_paused");value.put("available",available);if(available)value.put("resolved_id",m.getString("id")).put("revision",m.getLong("revision")).put("dependencies",dependencies(m,new HashSet<>(seen),depth+1));result.put(value);
  }return result;
 }
 private JSONObject report(JSONObject old,JSONObject p)throws Exception{
  String reason=p.getString("reason");if(!Set.of("network","account_permission","user_cancelled","observation","page_changed","method_error","outcome_unknown").contains(reason))throw new IllegalArgumentException("Invalid failure reason");
  String key=SkillFileStore.hash(old.getString("id")+":"+p.getString("execution_id")+":"+p.optString("capability_id"));
  if(store.rows(db,"SELECT id FROM skill_uses WHERE id=?",key).length()>0)return new JSONObject().put("merge_status","unchanged");
  db.execSQL("INSERT INTO skill_uses VALUES(?,?,?,?,?,?,?)",new Object[]{key,old.getString("id"),old.getLong("revision"),"","failure",reason,WorkspaceStore.now()});
  if(old.optBoolean("enabled",true)&&Set.of("page_changed","method_error").contains(reason))setHealth(old,p.optString("capability_id"),reason.equals("method_error")?"auto_paused":"needs_revalidation",store.skillAppVersion(old.optString("package")),"");
  return new JSONObject().put("merge_status","evidence_added").put("health",health(old));
 }
 private JSONArray health(JSONObject m)throws Exception{return store.rows(db,"SELECT capability_id,state,app_version,evidence_id,updated_at FROM skill_health WHERE skill_id=? AND revision=?",m.getString("id"),Long.toString(m.getLong("revision")));}
 private JSONObject health(JSONObject m,String capability)throws Exception{JSONArray rows=store.rows(db,"SELECT state,app_version FROM skill_health WHERE skill_id=? AND revision=? AND capability_id=?",m.getString("id"),Long.toString(m.getLong("revision")),capability);return rows.length()==0?new JSONObject().put("state",m.optString("lifecycle","unverified")):rows.getJSONObject(0);}
 private void setHealth(JSONObject m,String capability,String state,String version,String evidence)throws Exception{if(!capability.isEmpty()){boolean found=capability.equals(m.optString("capability_id"));JSONArray caps=m.optJSONArray("capabilities");if(caps!=null)for(int i=0;i<caps.length();i++)found|=capability.equals(caps.getJSONObject(i).getString("capability_id"));if(!found)throw new IllegalArgumentException("Unknown skill capability");}db.execSQL("INSERT OR REPLACE INTO skill_health VALUES(?,?,?,?,?,?,?)",new Object[]{m.getString("id"),m.getLong("revision"),capability,state,version,evidence,WorkspaceStore.now()});}
 private void verified(JSONObject m,JSONObject p,JSONObject evidence)throws Exception{setHealth(m,p.optString("capability_id"),"available",evidence.optString("app_version"),p.getString("evidence_id"));}
 private JSONObject publish(JSONObject m,String body,JSONObject assets,long expected)throws Exception{String id=WorkspaceStore.id();ledger(id,m.getString("id"),expected,expected+1,"prepared",SkillFileStore.hash(body+assets.toString()),"");try{JSONObject result=files.publish(id,m,body,assets,expected);ledger(id,m.getString("id"),expected,expected+1,"published",SkillFileStore.hash(body+assets.toString()),"");result.remove("assets");return result;}catch(Exception e){ledger(id,m.getString("id"),expected,expected+1,"failed",SkillFileStore.hash(body+assets.toString()),e.toString());throw e;}}
 private void ledger(String id,String skill,long expected,long target,String state,String hash,String error){ContentValues v=new ContentValues();v.put("id",id);v.put("skill_id",skill);v.put("expected_revision",expected);v.put("target_revision",target);v.put("state",state);v.put("asset_hash",hash);v.put("error",error);v.put("created_at",WorkspaceStore.now());v.put("updated_at",WorkspaceStore.now());db.insertWithOnConflict("skill_publications",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
}
